// SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

contract AuditRegistry {

    struct AuditRecord {
        bytes32 auditHash;
        uint256 timestamp;
        address recordedBy;
    }

    mapping(string => AuditRecord) private auditRecords;

    event AuditRecorded(
        string applicationId,
        bytes32 auditHash,
        uint256 timestamp,
        address recordedBy
    );

    function recordAudit(
        string memory applicationId,
        bytes32 auditHash
    ) public {

        auditRecords[applicationId] = AuditRecord({
            auditHash: auditHash,
            timestamp: block.timestamp,
            recordedBy: msg.sender
        });

        emit AuditRecorded(
            applicationId,
            auditHash,
            block.timestamp,
            msg.sender
        );
    }

    function getAudit(
        string memory applicationId
    )
        public
        view
        returns (
            bytes32 auditHash,
            uint256 timestamp,
            address recordedBy
        )
    {
        AuditRecord memory record = auditRecords[applicationId];

        return (
            record.auditHash,
            record.timestamp,
            record.recordedBy
        );
    }
}
